describe('Task Creation Form', () => {
  beforeEach(() => {
    cy.visit('/tasks');
  });

  it('should successfully create a new task by filling out the form and clicking Save', () => {
    // Intercept the API call to create a task
    cy.intercept('POST', '/api/tasks').as('createTask');

    // Fill out the form
    cy.get('[data-testid="task-title-input"]').type('Complete project report');
    cy.get('[data-testid="task-description-input"]').type('Prepare and submit the final report to management');
    cy.get('[data-testid="task-due-date-input"]').type('2023-05-10');
    cy.get('[data-testid="task-priority-select"]').select('High');

    // Click the Save button
    cy.get('[data-testid="save-task-button"]').click();

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Task created successfully');

    // Verify task appears in list
    cy.get('[data-testid="task-list"]').should('contain', 'Complete project report');

    // Verify API call was made
    cy.wait('@createTask').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });
  });

  it('should display validation error when saving an empty task', () => {
    // Intercept the API call
    cy.intercept('POST', '/api/tasks').as('createTask');

    // Fill out only the title field
    cy.get('[data-testid="task-title-input"]').type('');

    // Click the Save button
    cy.get('[data-testid="save-task-button"]').click();

    // Verify validation error message appears
    cy.get('[data-testid="validation-error-message"]').should('be.visible').should('contain', 'Task title is required');

    // Verify form is still visible
    cy.get('[data-testid="task-form"]').should('be.visible');

    // Verify API call was not made
    cy.wait('@createTask').then((interception) => {
      expect(interception.request.body).to.not.exist;
    });
  });
});
